if isClient then
    Plugins.Require("shop", "client.ui.GUIFactory")
    Plugins.Require("shop", "client.mgr.CShopMgr")
    Plugins.Require("shop", "client.listener.ShopListener")
    Plugins.Require("shop", "client.ui.GUIFactory")
