local handlers = {}

function handlers.onPlayerReady(player)
    if isClient then
        return
    end
    ---@type SShopMgr
    local SShopMgr = T(Global, "SShopMgr")
    SShopMgr:syncShop(player.userId)
end

function handlers.onSyncPermissionRole(new, old)
    if isServer then
        return
    end
    if UIHelper.isGameGUILayoutShow("GUICustomShop") then
        ---@type UICustomShopLayout
        local GUICustomShop = UIHelper.newGameGUILayout("GUICustomShop")
        local oldStatus = old == Define.CustomGamePermissionRole.Admin or old == Define.CustomGamePermissionRole.Owner
        local newStatus = new == Define.CustomGamePermissionRole.Admin or new == Define.CustomGamePermissionRole.Owner
        if GUICustomShop.editStatus and oldStatus and not newStatus then
            GUICustomShop:hide()
        else
            GUICustomShop:updateBtns()
        end
    end
end

return function(name, ...)
    if type(handlers[name]) ~= "function" then
        return
    end
    return handlers[name](...)
end